        )
        {
            $breakpoints: map-merge(
                $breakpoints,
                (
                    $bp: round($size * $factor) + px,
                )
            );
        }
    }

    $spacing-values: map-merge(
        $spacing-values,
        (
            $size: $breakpoints,
        )
    );
